mapper.select:
WITH key_asset_report_counts AS ( SELECT key_asset_report_id, COUNT(*) AS total_count FROM key_asset_report_org GROUP BY key_asset_report_id ), matching_permissions AS ( SELECT up.key_asset_report_id, COUNT(up.key_asset_report_id) AS org_count FROM key_asset_report_org up WHERE up.org_id IN
#{item}
GROUP BY up.key_asset_report_id ) SELECT kar.* FROM key_asset_report kar LEFT JOIN matching_permissions mp ON kar.id = mp.key_asset_report_id LEFT JOIN key_asset_report_counts karc ON kar.id = karc.key_asset_report_id WHERE kar.tenant_uid = #{tenantUid} AND ( karc.total_count is null OR (mp.org_count >= COALESCE(karc.total_count, 0) AND karc.total_count IS NOT NULL) )
AND kar.report_year =#{reportYear}
AND kar.report_type =#{reportType}
AND kar.asset_name like concat('%',#{assetName},'%')
AND kar.asset_dept_name like concat('%',#{assetDeptName},'%')
AND kar.form_filler like concat('%',#{formFiller},'%')
order by kar.create_time desc LIMIT #{page} OFFSET #{offset}

WITH key_asset_report_counts AS ( SELECT key_asset_report_id, COUNT(*) AS total_count FROM key_asset_report_org GROUP BY key_asset_report_id ), matching_permissions AS ( SELECT up.key_asset_report_id, COUNT(up.key_asset_report_id) AS org_count FROM key_asset_report_org up WHERE up.org_id IN
#{item}
GROUP BY up.key_asset_report_id ) SELECT count(kar.*) FROM key_asset_report kar LEFT JOIN matching_permissions mp ON kar.id = mp.key_asset_report_id LEFT JOIN key_asset_report_counts karc ON kar.id = karc.key_asset_report_id WHERE kar.tenant_uid = #{tenantUid} AND ( karc.total_count is null OR (mp.org_count >= COALESCE(karc.total_count, 0) AND karc.total_count IS NOT NULL) )
AND kar.report_year =#{reportYear}
AND kar.report_type =#{reportType}
AND kar.asset_name like concat('%',#{assetName},'%')
AND kar.asset_dept_name like concat('%',#{assetDeptName},'%')
AND kar.form_filler like concat('%',#{formFiller},'%')
